.theme-day .memory-partner-card{background:#f4f0e9;border:1px solid var(--theme-accent-day);box-shadow:0 4px 6px rgba(0,0,0,0.05)}.theme-day .memory-partner-card:hover{transform:scale(1.05);box-shadow:0 6px 12px rgba(0,0,0,0.1)}
