.back-btn{background:transparent;border:1px solid var(--theme-accent);color:var(--theme-accent);padding:5px 15px;border-radius:20px;cursor:pointer;margin-bottom:10px;transition:all .2s var(--ease-out-fast);flex-shrink:0;align-self:flex-start}
.back-btn:hover{background:var(--theme-primary);color:var(--theme-secondary);border-color:var(--theme-primary)}
.back-btn:active{transform:scale(0.95)}
.inspector-modal-content{display:flex;flex-direction:column;align-items:center;text-align:center;padding:clamp(20px, 4vw, 40px)}
.inspector-modal-content .inspector-icon-container{width:100px;height:100px;display:flex;align-items:center;justify-content:center;border-radius:var(--border-radius);margin-bottom:20px}
.inspector-modal-content .item-icon{width:60%;height:60%}
.theme-day .inspector-modal-content .inspector-icon-container{background-color:rgba(0,0,0,0.03);border:1px solid var(--theme-accent-day)}
.theme-night .inspector-modal-content .inspector-icon-container{background:radial-gradient(circle, hsla(251,100%,76%,0.1) 0%, transparent 70%)}
.theme-night .inspector-modal-content .item-icon{filter:drop-shadow(0 0 10px var(--theme-primary-night))}
.inspector-text-content h3{margin:0 0 5px;font-size:1.8em}
.inspector-text-content .item-type-badge{margin-bottom:15px;display:inline-block}
.inspector-text-content p{font-size:1.1em;line-height:1.8;margin-bottom:20px}
.theme-day .inspector-text-content p{font-family:var(--font-serif)}
.inspector-acquisition-log{width:100%;padding-top:15px;margin-top:15px;border-top:1px solid var(--theme-accent);font-size:0.9em;opacity:0.8;text-align:left}
