        },
        logTypes: {
            dialogue: '<svg class="log-icon" viewBox="0 0 24 24"><path fill="currentColor" d="M20 2H4c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h14l4 4V4c0-1.1-.9-2-2-2zM6 9h12v2H6V9zm8 5H6v-2h8v2zm4-6H6V6h12v2z"/></svg>',
            discovery: '<svg class="log-icon" viewBox="0 0 24 24"><path fill="currentColor" d="M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5C21.27 7.61 17 4.5 12 4.5zm0 10c-2.48 0-4.5-2.02-4.5-4.5S9.52 5.5 12 5.5s4.5 2.02 4.5 4.5-2.02 4.5-4.5 4.5zm0-7C10.62 7.5 9.5 8.62 9.5 10s1.12 2.5 2.5 2.5 2.5-1.12 2.5-2.5S13.38 7.5 12 7.5z"/></svg>',
            combat: '<svg class="log-icon" viewBox="0 0 24 24"><path fill="currentColor" d="M19.78 2.22a.996.996 0 0 0-1.41 0L2.22 18.37a.996.996 0 1 0 1.41 1.41L19.78 3.63a.996.996 0 0 0 0-1.41zM4.37 2.22L2.22 4.37l7.46 7.46-1.42 1.42-4.24-4.24-1.41 1.41 4.24 4.24-2.83 2.83 1.41 1.41 2.83-2.83 1.42 1.42-7.46 7.46 2.15 2.15 16.16-16.16-2.15-2.15z"/></svg>',
            action: '<svg class="log-icon" viewBox="0 0 24 24"><path fill="currentColor" d="M17.2 6.8l-1.4-1.4-9 9 1.4 1.4 9-9zM13 2L4 11v9h9l9-9V2h-9zm0 2h2.59l-9 9H4v-2.59l9-9zM6 19v-5.59l5.59-5.59L17.17 13 11 19.17V19H6z"/></svg>',
            sexLog: '<svg class="log-icon" viewBox="0 0 24 24"><path fill="currentColor" d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>'
        }
    },
    init(rawData) {
        try {
            this.data = this.universalDataAdapter(rawData);
            this.renderInitialHTML();
            this.applyTheme();
            this.setupProgressObserver();
            this.renderAll();
            this.attachEventListeners();
        } catch (e) {
            this.renderError(e);
        }
    },
    universalDataAdapter(raw) {
        const defaultTemplate = { protagonist: {}, quest: {}, relationships: [], log: [], sexLog: [] };
        let parsed;
        try {
            parsed = JSON.parse(raw);
        } catch (e) {
            console.error("MaestroApp: JSON parsing failed.", e);
            return { ...defaultTemplate, parseError: true, errorMessage: e.message };
        }
        return parsed;
    },
    getLuminance(hex) {
        if (!hex) return 0;
        const rgb = parseInt(hex.slice(1), 16);
        const r = (rgb >> 16) & 0xff;
        const g = (rgb >> 8) & 0xff;
        const b = (rgb >> 0) & 0xff;
        return 0.2126 * r + 0.7152 * g + 0.0722 * b;
    },
    getIntelligentGlow(color) {
        const luminance = this.getLuminance(color);
        return luminance > 128 ? 'rgba(0,0,0,0.3)' : 'rgba(255,255,255,0.5)';
    },
    getMentalStateStyle(state) {
        if (!state) return { color: 'var(--theme-text)' };
        if (state.includes('暴怒') || state.includes('愤怒')) return { color: '#E74C3C', fontWeight: 'bold' };
        if (state.includes('愉悦') || state.includes('开心') || state.includes('兴奋')) return { color: '#2ECC71' };
        if (state.includes('悲伤') || state.includes('沮丧')) return { color: '#3498DB' };
        if (state.includes('恐惧') || state.includes('紧张')) return { color: '#9B59B6' };
        if (state.includes('平静') || state.includes('冷静')) return { color: '#1ABC9C' };
        return { color: 'var(--theme-text)' };
    },
    renderAll() {
        if (this.data.parseError) {
            this.renderError(new Error(this.data.errorMessage));
            return;
        }
        const p = this.data?.protagonist;
        const q = this.data?.quest;
        document.getElementById('status-card').style.setProperty('--status-glow-color', this.getIntelligentGlow(p?.statusColor));
        this.updateText('protagonist-name', p?.name ?? '观察者');
        this.updateText('protagonist-date', p?.date ?? '未知日期');
        this.updateText('protagonist-time', p?.time ?? '未知时间');
        this.updateText('protagonist-weather', p?.weather ?? '未知天气');
        this.updateText('protagonist-identity', p?.identity ?? '未知身份');
        this.updateText('protagonist-location', p?.location ?? '未知地点');
        this.setProgress('protagonist-stamina-bar', p?.stamina);
        this.setProgress('protagonist-energy-bar', p?.energy);
        const mentalStateEl = document.getElementById('protagonist-mental-state');
        if(mentalStateEl) {
            this.updateText('protagonist-mental-state', p?.mentalState ?? '未知');
            Object.assign(mentalStateEl.style, this.getMentalStateStyle(p?.mentalState));
        }
        this.updateText('protagonist-outfit', p?.outfit ?? '未知着装');
        this.updateText('main-quest', q?.main ?? '暂无任务');
        this.renderInventory(p?.inventory);
        this.renderRelationships();
        this.renderChorusOfSouls();
        this.renderLog();
        this.renderMemories();
        this.observeProgressBars();
    },
    renderInventory(inventory) {
        const container = document.getElementById('inventory-container');
        if (!container) return;
        const typeMap = { weapon: '武器', consumable: '消耗品', keyItem: '关键物品' };
        let html = '';
        (inventory ?? []).forEach((item, index) => {
            const icon = this.icons.itemTypes[item?.type] || this.icons.itemTypes.unknown;
            const typeText = typeMap[item?.type] || '未知';
            const animDelay = index < 20 ? `animation-delay: ${index * 0.05}s;` : '';
            html += `<div class="inventory-item" data-item-index="${index}" style="${animDelay}">${icon}<div class="item-details"><h5>${item?.name ?? '未知物品'} ${item?.quantity > 1 ? `x${item.quantity}` : ''}</h5></div><span class="item-type-badge">${typeText}</span></div>`;
        });
        container.innerHTML = html || '<p style="text-align:center;opacity:0.7;grid-column:1/-1;">物品栏为空</p>';
    },
    showItemInspector(item) {
        const typeMap = { weapon: '武器', consumable: '消耗品', keyItem: '关键物品' };
        const modal = document.getElementById('item-inspector-modal');
        this.updateHTML('inspector-modal-icon', this.icons.itemTypes[item?.type] || this.icons.itemTypes.unknown);
        this.updateText('inspector-modal-name', `${item?.name ?? '未知物品'} ${item?.quantity > 1 ? `x${item.quantity}` : ''}`);
        this.updateText('inspector-modal-type', typeMap[item?.type] || '未知');
        this.updateText('inspector-modal-description', item?.description ?? '无详细描述。');
        const acqLog = document.getElementById('inspector-acquisition-log');
        if (item?.acquisition?.method) {
            this.updateText('inspector-modal-acq-time', item.acquisition.timestamp ?? '未知');
            this.updateText('inspector-modal-acq-method', item.acquisition.method);
            acqLog.style.display = 'block';
        } else {
            acqLog.style.display = 'none';
        }
        modal.classList.add('show');
        document.body.classList.add('modal-open');
    },
    hideItemInspector() {
        document.getElementById('item-inspector-modal').classList.remove('show');
        if (!document.querySelector('#character-dossier-modal.show')) {
            document.body.classList.remove('modal-open');
        }
    },
    renderRelationships(filter = '') {
        const container = document.getElementById('relationships-panel-container');
        const filteredData = (this.data?.relationships ?? []).filter(char => (char?.name ?? '').toLowerCase().includes(filter.toLowerCase()));
        let html = '';
        filteredData.forEach((char, index) => {
            const originalIndex = (this.data?.relationships ?? []).findIndex(c => c?.name === char?.name);
            const charColor = char?.dossier?.basicInfo?.color ?? 'var(--theme-accent)';
            const favor = char?.favor ?? '??/100';
            const animDelay = index < 20 ? `animation-delay: ${index * 0.05}s;` : '';
            html += `<div class="relationship-card" data-char-index="${originalIndex}" style="--char-color: ${charColor}; ${animDelay}"><h4>${char?.name ?? '未知角色'}</h4><p class="social-status">${char?.dossier?.basicInfo?.social ?? '关系未知'}</p><div class="favor-rating">好感: ${favor}</div></div>`;
        });
        container.innerHTML = html || `<p style="text-align:center;opacity:0.7;grid-column:1/-1;">暂无人际关系</p>`;
    },
    renderChorusOfSouls() {
        const container = document.getElementById('chorus-of-souls');
        if (!container) return;
        const characters = this.data?.currentSceneStatus?.characters;
        if (!characters || characters.length === 0) {
            container.innerHTML = '<p style="text-align:center;opacity:0.7;">当前场景无角色状态</p>';
            return;
        }
        let html = '';
        characters.forEach(char => {
            html += `<div class="chorus-voice-card"><div class="chorus-voice-name">${char.name ?? '未知角色'}</div><span class="chorus-voice-monologue">“${char.monologue ?? '...'}”</span><span class="chorus-voice-actions">${char.actions ?? '...'}</span></div>`;
        });
        container.innerHTML = html;
    },
    renderLog() {
        const container = document.getElementById('log-container');
        const filteredLogs = (this.data?.log ?? []).filter(entry => this.state.currentLogFilter === 'all' || entry?.type === this.state.currentLogFilter);
        let html = '';
        filteredLogs.forEach((entry, index) => {
            const icon = this.icons.logTypes[entry?.type] || this.icons.logTypes.action;
            const animDelay = index < 20 ? `animation-delay: ${index * 0.05}s;` : '';
            html += `<div class="log-entry" style="${animDelay}">${icon}<div class="log-content"><p>${entry?.content ?? '日志内容缺失'}</p><span class="log-meta">${entry?.timestamp ?? ''}</span></div></div>`;
        });
        container.innerHTML = html || '<p style="text-align:center;opacity:0.7;">暂无历史日志</p>';
    },
    renderMemories() {
        const partnerGrid = document.getElementById('memory-partner-grid');
        const logContainer = document.getElementById('sex-log-container');
        const backBtn = document.getElementById('back-to-partners-btn');
        if (!this.state.selectedMemoryPartner) {
            partnerGrid.style.display = 'grid';
            logContainer.style.display = 'none';
            backBtn.style.display = 'none';
            const partners = new Map();
            (this.data?.sexLog ?? []).forEach(log => {
                if (log?.partner) partners.set(log.partner, (partners.get(log.partner) || 0) + 1);
            });
            let html = '';
            for (const [name, count] of partners) {
                html += `<div class="memory-partner-card" data-partner-name="${name}"><div class="partner-name">${name}</div><div class="memory-count">${count} 回忆</div></div>`;
            }
            partnerGrid.innerHTML = html || '<p style="text-align:center;opacity:0.7;grid-column:1/-1;">暂无回忆</p>';
        } else {
            partnerGrid.style.display = 'none';
            logContainer.style.display = 'block';
            backBtn.style.display = 'inline-block';
            const filteredLogs = (this.data?.sexLog ?? []).filter(log => log?.partner === this.state.selectedMemoryPartner);
            let html = '';
            for(const entry of filteredLogs) {
                html += `<div class="sex-log-card"><div class="sex-log-card-header">${this.icons.logTypes.sexLog}<div class="sex-log-card-header-text"><div class="sex-log-title-line"><div class="sex-log-title">${entry?.title ?? '无标题'}</div><div class="sex-log-partner">与 <span>${entry?.partner}</span></div></div></div><div class="sex-log-timestamp">${entry?.timestamp ?? ''}</div></div><div class="sex-log-card-body"><div><p>${entry?.summary ?? '回忆内容缺失'}</p></div></div></div>`;
            }
            logContainer.innerHTML = html;
        }
    },
    selectMemoryPartner(partnerName) {
        this.state.selectedMemoryPartner = partnerName;
        this.renderMemories();
    },
    showPartnerSelection() {
        this.state.selectedMemoryPartner = null;
        this.renderMemories();
    },
    showCharacterDossier(index, element) {
        this.state.lastFocusedElement = element;
        this.state.currentCharacterIndex = index;
        const char = this.data?.relationships?.[index];
        if (!char) return;
        const modal = document.getElementById('character-dossier-modal');
        const dossier = char.dossier ?? {};
        this.updateText('modal-char-name', dossier.basicInfo?.name ?? char.name ?? '未知角色');
        this.updateText('modal-char-identity', dossier.basicInfo?.identity ?? 'N/A');
        this.updateText('modal-char-social', dossier.basicInfo?.social ?? 'N/A');
        this.setProgress('modal-favor-bar', dossier.dynamicValues?.favor);
        this.setProgress('modal-stamina-bar', dossier.dynamicValues?.stamina);
        this.setProgress('modal-energy-bar', dossier.dynamicValues?.energy);
        this.updateText('modal-char-quest', dossier.basicInfo?.quest ?? 'N/A');
        this.updateText('modal-sex-status', dossier.sexStatus?.status ?? 'N/A');
        this.updateText('modal-sex-experience', dossier.sexStatus?.experience ?? '');
        this.updateText('modal-sex-details', dossier.sexStatus?.details ?? '');
        ['appearance', 'outfit', 'physiology'].forEach(cat => {
            const grid = modal.querySelector(`#modal-${cat}-section .detail-card-grid`);
            let html = '';
            const sourceData = dossier[cat];
            if (sourceData && typeof sourceData === 'object' && !Array.isArray(sourceData)) {
                Object.entries(sourceData).forEach(([key, value], i) => {
                    const animDelay = i < 20 ? `animation-delay:${i * 0.05}s` : '';
                    html += `<div class="detail-card" style="${animDelay}"><strong>${key}</strong><p>${value ?? '...'}</p></div>`;
                });
            } else if (typeof sourceData === 'string' && sourceData.length > 0) {
                html = `<div class="detail-card"><strong>概览</strong><p>${sourceData}</p></div>`;
            }
            grid.innerHTML = html || '<p style="opacity:0.7;text-align:center;">无相关信息</p>';
        });
        const modalNavBar = modal.querySelector('#modal-nav-bar');
        this.setupNav(modalNavBar);
        this.setActive(modalNavBar.querySelector('[data-scroll-target="#modal-overview-section"]'));
        modal.querySelector('.content-scroll-area').scrollTop = 0;
        this.setupModalObserver();
        modal.classList.add('show');
        document.body.classList.add('modal-open');
        modal.querySelector('.modal-close').focus();
        this.observeProgressBars(modal);
    },
    closeCharacterModal() {
        document.getElementById('character-dossier-modal').classList.remove('show');
        if (!document.querySelector('#item-inspector-modal.show')) {
            document.body.classList.remove('modal-open');
        }
        if (this.state.modalScrollObserver) this.state.modalScrollObserver.disconnect();
        if (this.state.lastFocusedElement) {
            this.state.lastFocusedElement.focus();
            this.state.lastFocusedElement = null;
        }
    },
    setupNav(navBar) {
        const links = navBar.querySelectorAll('.nav-link');
        links.forEach(link => {
            link.addEventListener('click', e => {
                const target = e.target.closest('.nav-link');
                if (!target) return;
                if (target.dataset.target) {
                    if (target.classList.contains('active')) return;
                    const panelContainer = navBar.closest('.status-card, .modal-content').querySelector('.content-panels, .content-scroll-area');
                    this.setActive(target);
                    if (panelContainer.querySelector('.panel.active')) panelContainer.querySelector('.panel.active').classList.remove('active');
                    panelContainer.querySelector(`#${target.dataset.target}`).classList.add('active');
                } else if (target.dataset.scrollTarget) {
                    const scrollTargetEl = document.querySelector(target.dataset.scrollTarget);
                    if (scrollTargetEl) {
                        if (this.state.modalScrollObserver) this.state.modalScrollObserver.disconnect();
                        scrollTargetEl.scrollIntoView({ behavior: 'smooth' });
                        setTimeout(() => this.setupModalObserver(), 800);
                    }
                }
            });
        });
        this.updateSlider(navBar.querySelector('.nav-link.active'));
    },
    setupModalObserver() {
        const scrollArea = document.getElementById('modal-scroll-area');
        const sections = scrollArea.querySelectorAll('.dossier-section');
        const options = { root: scrollArea, rootMargin: "-40% 0px -60% 0px", threshold: 0 };
        if (this.state.modalScrollObserver) this.state.modalScrollObserver.disconnect();
        this.state.modalScrollObserver = new IntersectionObserver(entries => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const targetId = entry.target.id;
                    const activeLink = document.querySelector(`#modal-nav-bar .nav-link[data-scroll-target="#${targetId}"]`);
                    if (activeLink) this.setActive(activeLink);
                }
            });
        }, options);
        sections.forEach(section => this.state.modalScrollObserver.observe(section));
    },
    setupProgressObserver() {
        this.state.progressObserver = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('is-visible');
                    observer.unobserve(entry.target);
                }
            });
        }, { threshold: 0.5 });
    },
    observeProgressBars(context = document) {
        if (!this.state.progressObserver) return;
        const bars = context.querySelectorAll('.progress-bar');
        bars.forEach(bar => this.state.progressObserver.observe(bar));
    },
    setActive(target) {
        if (!target) return;
        const navBar = target.closest('.nav-bar, #mobile-nav-menu');
        if (!navBar) return;
        const targetIdentifier = target.dataset.target || target.dataset.scrollTarget;
        navBar.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));
        const activeLinks = navBar.querySelectorAll(`.nav-link[data-target="${targetIdentifier}"], .nav-link[data-scroll-target="${targetIdentifier}"]`);
        activeLinks.forEach(l => l.classList.add('active'));
        this.updateSlider(navBar.querySelector('.nav-link.active'));
    },
    updateSlider(active) {
        const slider = active?.closest('.nav-tabs-container')?.querySelector('.nav-slider');
        if (active && slider) {
            slider.style.width = `${active.offsetWidth}px`;
            slider.style.transform = `translateX(${active.offsetLeft}px)`;
        }
    },
    toggleTheme() {
        const body = document.body;
        const isDay = body.classList.contains('theme-day');
        const newTheme = isDay ? 'theme-night' : 'theme-day';
        body.classList.replace(isDay ? 'theme-day' : 'theme-night', newTheme);
        localStorage.setItem('theme', newTheme);
    },
    applyTheme() {
        const savedTheme = localStorage.getItem('theme') || 'theme-night';
        document.body.classList.add(savedTheme);
    },
    attachEventListeners() {
        document.addEventListener('click', e => {
            const target = e.target;
            if (target.closest('.theme-switcher')) { this.toggleTheme(); return; }
            if (target.closest('.modal-close') || target.matches('.modal-backdrop')) {
                if (target.closest('#item-inspector-modal')) { this.hideItemInspector(); }
                if (target.closest('#character-dossier-modal')) { this.closeCharacterModal(); }
                return;
            }
            const itemTarget = target.closest('.inventory-item');
            if (itemTarget?.dataset.itemIndex) {
                const item = this.data?.protagonist?.inventory?.[parseInt(itemTarget.dataset.itemIndex)];
                if(item) this.showItemInspector(item);
                return;
            }
            const charTarget = target.closest('.relationship-card');
            if (charTarget?.dataset.charIndex) {
                this.showCharacterDossier(parseInt(charTarget.dataset.charIndex), charTarget);
                return;
            }
            const partnerTarget = target.closest('.memory-partner-card');
            if (partnerTarget?.dataset.partnerName) {
                this.selectMemoryPartner(partnerTarget.dataset.partnerName);
                return;
            }
            const logHeader = target.closest('.sex-log-card-header');
            if (logHeader) {
                logHeader.parentElement.classList.toggle('open');
                return;
            }
            const filterBtn = target.closest('.log-filter-btn');
            if (filterBtn) {
                this.state.currentLogFilter = filterBtn.dataset.filter;
                document.querySelectorAll('#log-filters .log-filter-btn').forEach(btn => btn.classList.remove('active'));
                filterBtn.classList.add('active');
                this.renderLog();
                return;
            }
            const backBtn = target.closest('#back-to-partners-btn');
            if (backBtn) {
                this.showPartnerSelection();
                return;
            }
            const mobileMenuToggle = target.closest('#mobile-menu-toggle');
            if (mobileMenuToggle) {
                mobileMenuToggle.classList.toggle('open');
                document.getElementById('mobile-nav-menu').classList.toggle('open');
                return;
            }
            const mobileNavLink = target.closest('#mobile-nav-menu .nav-link');
            if (mobileNavLink) {
                document.getElementById('mobile-menu-toggle').classList.remove('open');
                document.getElementById('mobile-nav-menu').classList.remove('open');
            }
            const logViewToggle = target.closest('.log-view-toggle');
            if (logViewToggle) {
                document.querySelectorAll('.log-view-toggle').forEach(t => t.classList.remove('active'));
                logViewToggle.classList.add('active');
                document.querySelectorAll('.log-view-content').forEach(c => c.classList.add('hidden'));
                document.getElementById(logViewToggle.dataset.view).classList.remove('hidden');
            }
        });
        this.setupNav(document.getElementById('main-nav-bar'));
        this.setupNav(document.getElementById('mobile-nav-menu'));
        const searchInput = document.getElementById('relationship-search');
        if (searchInput) {
            searchInput.addEventListener('input', e => this.renderRelationships(e.target.value));
        }
        document.addEventListener('keydown', e => {
            if (e.key === 'Escape') {
                if (document.querySelector('#item-inspector-modal.show')) this.hideItemInspector();
                if (document.querySelector('#character-dossier-modal.show')) this.closeCharacterModal();
            }
        });
    },
    updateText(id, text) { const el = document.getElementById(id); if (el) el.textContent = text; },
    updateHTML(id, html) { const el = document.getElementById(id); if (el) el.innerHTML = html; },
    setProgress(barId, val) {
        const bar = document.getElementById(barId);
        if (bar) {
            const [cur, max] = (String(val) ?? '0/100').split('/').map(Number);
            const pct = isNaN(cur) || isNaN(max) || max === 0 ? 0 : (cur / max) * 100;
            const innerBar = bar.querySelector('div');
            const span = bar.querySelector('span');
            if (innerBar) innerBar.style.setProperty('--target-width', pct + '%');
            if (span) span.textContent = val ?? 'N/A';
        }
    },
    renderError(e) { document.getElementById('maestro-container').innerHTML = `<div class="status-card error-message"><p>状态栏数据解析失败！</p><p>请检查 &lt;state_bar&gt; 标签内的内容是否为合法的JSON格式。</p><p style="font-size:12px;opacity:0.7;">错误: ${e.message}</p></div>`; },
    renderInitialHTML() {
        document.getElementById('maestro-container').innerHTML = `
<div class="status-card main-view" id="status-card">
